/**
 * Jinx Alchemist + Organ Grinder: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Alchemist
 * Wiki: https://wiki.bloodontheclocktower.com/Organ_Grinder
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/ability.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { alchemistAs, bagNotes } from './alchemist.test-support.ts';

describe('Alchemist + Organ Grinder jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alchemist', 'organgrinder');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alchemist')?.name).toBe('Alchemist');
		expect(data.byId.get('organgrinder')?.name).toBe('Organ Grinder');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alchemist', 'organgrinder'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alchemist'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['organgrinder'])).not.toContain(jinx);
	});

	describe('with an Alchemist-Organ Grinder, the Organ Grinder is in play, and both sober are drunk', () => {
		// Seat 0 the Alchemist-Organ Grinder, seat 2 the real Organ Grinder.
		const base = alchemistAs('organgrinder', ['chef', 'organgrinder', 'imp', 'poisoner']);
		const reasons = (s: typeof base, seat: number) =>
			abilityState(s.game, s.seat(seat), s.characters).impairments.map((i) => i.reason);

		it("is data in the Alchemist's rules", () => {
			// Wiki: "If the Alchemist has the Organ Grinder ability, the Organ Grinder is in play. If both are sober, both are drunk."
			expect(jinxRulesBetween('alchemist', 'organgrinder', committedCharacters())).toEqual({
				impairs: {
					kind: 'drunk',
					unlessImpaired: true,
					when: ['has-partner-ability'],
					who: 'both'
				},
				partnerInPlay: {}
			});
		});

		it('notes the real Organ Grinder at setup when the Alchemist is chosen', () => {
			// Wiki: "If the Alchemist has the Organ Grinder ability, the Organ Grinder is in play."
			const note =
				'Alchemist with the Organ Grinder ability: the Organ Grinder is in play too, and while both are sober, both are drunk.';
			expect(bagNotes('organgrinder')).toContain(note);
			expect(bagNotes('organgrinder', false)).not.toContain(note);
		});

		it('makes both drunk while both are sober', () => {
			// Wiki: "If both are sober, both are drunk."
			expect(reasons(base, 0)).toEqual(['drunk']);
			expect(reasons(base, 2)).toEqual(['drunk']);
			expect(abilityState(base.game, base.seat(0), base.characters).impairments).toMatchObject([
				{ source: { characterId: 'organgrinder' } }
			]);
		});

		it('leaves the other one sober while one is poisoned', () => {
			// Wiki: "If both are sober, both are drunk."
			const s = base.poisoned(2);
			expect(reasons(s, 0)).toEqual([]);
			expect(reasons(s, 2)).toEqual(['poisoned']);
		});
	});
});
